output_text:
[
  {
    "id": "take_cart_before_shopping",
    "text": "A shopper is obliged to check out a cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "cart_checked_out": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_checked_out"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Required groceries should not be carried by hand; items may only be picked up when the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "handFull",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_loading",
    "text": "After placing any item in a cart, the shopper is obliged to return the cart to the designated return point before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "A cart may only be put down at the official cart return point, not abandoned elsewhere in the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "outside_cart_return_point": {
          "not": "cart_return_point"
        }
      },
      "events": {
        "cart_abandoned": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART",
              "outside_cart_return_point"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_abandoned"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "Once the cart has been returned, the shopper is obliged to proceed to the exit rather than continue shopping.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "cart_returned": {
          "pre": {
            "and": [
              "cart_return_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned",
      "discharge": "EXIT"
    }
  },
  {
    "id": "cart_one_way_far_shelf",
    "text": "When pushing a cart at the far shelf location, shoppers must not continue eastward through that aisle.",
    "abstraction": {
      "state_properties": {
        "far_shelf_position": "at(6,4)",
        "pushing_cart_at_far_shelf": {
          "and": [
            "far_shelf_position",
            "hasCart"
          ]
        }
      },
      "events": {
        "push_cart_east_from_far_shelf": {
          "pre": {
            "and": [
              "pushing_cart_at_far_shelf",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_from_far_shelf"
    }
  },
  {
    "id": "upper_cell_only_with_cart",
    "text": "The upper side cell at (1,1) is off-limits to shoppers on foot, but may be used while escorting a cart to the return point.",
    "abstraction": {
      "state_properties": {
        "upper_side_cell": "at(1,1)",
        "on_foot": {
          "not": "hasCart"
        },
        "on_foot_in_upper_side_cell": {
          "and": [
            "upper_side_cell",
            "on_foot"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "on_foot_in_upper_side_cell"
    }
  }
]
